27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	};
34	
35	const basePremiumOf = (items: Item[]): number =>
36	  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
37	
38	const quote = (step: Step): QuoteResult => {
39	  const basePremium = basePremiumOf(step.items);
40	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
41	
42	  return { premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE };
43	};
44	
45	export const runScenario = (scenario: Scenario): ScenarioResult => ({
46	  results: scenario.steps.map(quote),
47	});
